import{_ as r,o as s,c as o,a5 as a}from"./chunks/framework.DGp912Ge.js";const h=JSON.parse('{"title":"1. 사양 확인","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/add-on/specifications.md","filePath":"ko/guides/add-on/specifications.md","lastUpdated":1779437493000}'),n={name:"ko/guides/add-on/specifications.md"};function d(e,t,i,g,l,c){return s(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_1-사양-확인" tabindex="-1">1. 사양 확인 <a class="header-anchor" href="#_1-사양-확인" aria-label="Permalink to &quot;1. 사양 확인&quot;">​</a></h1><p><strong>목표:</strong> 추가 모듈(카메라, LiDAR, 컴퓨터, 센서 등)을 장착하기 <strong>전에</strong> 로봇의 기계·전기적 한계를 충족하는지 확인합니다.</p><p><strong>사전 조건:</strong> 없음. 새 모듈을 설치할 때마다 이 단계를 가장 먼저 수행하세요.</p><h2 id="rbq-10-핵심-한계" tabindex="-1">RBQ 10 핵심 한계 <a class="header-anchor" href="#rbq-10-핵심-한계" aria-label="Permalink to &quot;RBQ 10 핵심 한계&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>한계</th><th>중요한 이유</th></tr></thead><tbody><tr><td><strong>최대 적재량</strong></td><td><strong>15 kg</strong></td><td>로봇 상부에 장착되는 모든 모듈의 총 질량</td></tr><tr><td><strong>장착 인터페이스</strong></td><td><strong>상부 레일 (슬롯)</strong> + 스프링 너트</td><td>반복 가능하고 견고한 장착</td></tr><tr><td><strong>사용 가능 전원</strong></td><td><strong>54 V</strong>, <strong>12 V</strong></td><td>추가 모듈의 입력 전압/소비 전류 확인</td></tr><tr><td><strong>데이터 인터페이스</strong></td><td><strong>CAN ×1</strong>, <strong>기가비트 LAN ×3</strong></td><td>추가 모듈의 통신 인터페이스와 일치</td></tr><tr><td><strong>방진방수 등급</strong></td><td><strong>IP54</strong></td><td>추가 모듈로 인해 IP 등급이 저하되지 않도록</td></tr></tbody></table><p>전체 사양표(치수, 보행 속도, 경사, 센서 등)는 아래 매뉴얼 페이지를 참고하세요.</p><p><strong><a href="/RBQ/ko/manual/product-descriptions/general-specification.html">→ 전체 사양 (매뉴얼)</a></strong></p><h2 id="설치-전-체크리스트" tabindex="-1">설치 전 체크리스트 <a class="header-anchor" href="#설치-전-체크리스트" aria-label="Permalink to &quot;설치 전 체크리스트&quot;">​</a></h2><p>다음 단계로 넘어가기 전에 다음 항목을 확인하세요:</p><ul><li>[ ] 추가 모듈 + 기존 적재물 합산 질량 <strong>≤ 15 kg</strong></li><li>[ ] 무게중심이 <strong>로봇 본체 위쪽</strong>에 위치 (큰 오버행 회피)</li><li>[ ] 전원·데이터 인터페이스가 RBQ 10의 사양과 일치</li><li>[ ] 추가 모듈 무게중심의 <strong>X / Y / Z 오프셋을 측정 완료</strong> (3단계에서 필요)</li></ul><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p><strong>15 kg</strong> 적재 한도를 초과하거나 본체 중심에서 멀리 떨어진 위치에 무거운 모듈을 장착하면 보행 안정성이 떨어지고, 관절 부하가 증가하며, 부품 수명이 단축될 수 있습니다. 반드시 사양표를 먼저 확인하세요.</p></div></div><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>체크리스트를 통과했다면 레일에 모듈을 장착합니다:</p><p><strong><a href="/RBQ/ko/guides/add-on/rail-spring-nut.html">→ 2. 레일 &amp; 스프링 너트</a></strong></p>',14)])])}const u=r(n,[["render",d]]);export{h as __pageData,u as default};
